  assert.equal((await call('POST', '/v1/renown/xp', { character: A, xp: 1000 }, me.secret)).status, 200);
  tok = (await call('POST', '/v1/auth/token', { character: A }, me.secret)).body;
  assert.deepEqual([tok.level, tok.xp], [10, 6000]);
